/** Ngôn ngữ của nội dung (Hub, chủ đề, văn bản pháp lý): chỉ tiếng Việt và tiếng Anh. */
export type Locale = 'vi' | 'en';
/** Ngôn ngữ giao diện: 11 ngôn ngữ. Từ nào chưa dịch thì dùng tiếng Anh. */
export type UiLocale = 'vi' | 'en' | 'zh-Hans' | 'zh-Hant' | 'ko' | 'ru' | 'ja' | 'fr' | 'de' | 'es' | 'pt-BR';
export const UI_LOCALES: UiLocale[] = ['vi', 'en', 'zh-Hans', 'zh-Hant', 'ko', 'ru', 'ja', 'fr', 'de', 'es', 'pt-BR'];
export type Dict = Partial<Record<Key, string>>;
const extra: Partial<Record<UiLocale, Dict>> = {};
export function registerLocale(code: UiLocale, dict: Dict) { extra[code] = dict; }
export const contentLocale = (l: UiLocale): Locale => (l === 'vi' ? 'vi' : 'en');
export function translate(locale: UiLocale, key: Key, vars?: Record<string, string | number>) {
  let s = locale === 'vi' ? vi[key] : locale === 'en' ? en[key] : extra[locale]?.[key] ?? en[key];
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, String(v));
  return s;
}
